using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CompanionCorruptionStats : CorruptionStats
{
	[Header("Companion Components")]
	[SerializeField]
	private CompanionCorruptionGauge companionCorruptionGauge;

	[SerializeField]
	private GameObject aliveCompanion;

	[SerializeField]
	private bool companionForBattle;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private GameObject faintedCompanion;

	private int originalMaxCorruption;

	private int currentAugmentedWeldingAmount;

	private bool completelyCorrupted;

	public bool CompanionForBattle => companionForBattle;

	private CompanionSpriteControl companionSpriteControl => spriteControl as CompanionSpriteControl;

	public void ResetCompletelyCorrupted()
	{
		completelyCorrupted = false;
	}

	public void OnPlayerCompletelyCorruptedAnimation()
	{
		DisableAliveCompanion(playerCompletelyCorrupted: true);
		companionSpriteControl.PlayReceiveFatalDamage();
	}

	public void Initialize(int companionMaxCorruption, int currentCorruption)
	{
		base.currentCorruption = currentCorruption;
		maxCorruption = companionMaxCorruption;
		originalMaxCorruption = companionMaxCorruption;
		companionCorruptionGauge.Initialize(companionMaxCorruption);
		spawnFeedbackCoroutine = null;
		if (GameScenesUtils.IsBattleScene())
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction?.Invoke();
		}
	}

	public void EndOfBattleInitialize()
	{
		maxCorruption = originalMaxCorruption;
		companionSpriteControl.InitializeSkeletonAndLight();
		currentCorruption = 0f;
		companionCorruptionGauge.UpdateMaxCorruption(currentCorruption, (int)maxCorruption);
		if (GameScenesUtils.IsBattleScene())
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction?.Invoke();
		}
	}

	public override int Purify(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		amount = base.Purify(amount, source, corruptionPurifyModifierEnum, playSFX);
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.TempestPollenOmenAction?.Invoke(amount);
		}
		return amount;
	}

	public override int Corrupt(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		CompanionEffects obj = unitEffects as CompanionEffects;
		int num = obj.IsLinkRockPlateActiveGetCorruptionIncreaseAmount();
		amount += num;
		int num2 = obj.IsBoostLinkEffectActiveGetCorruptionIncreaseAmount();
		amount += num2;
		int num3 = obj.IsLinkEmpowerActiveGetCorruptionIncreaseAmount();
		amount += num3;
		int num4 = obj.IsLinkThornActiveGetCorruptionIncreaseAmount();
		amount += num4;
		return base.Corrupt(amount, source, corruptionPurifyModifierEnum, playSFX);
	}

	public void InstantlyDefeatCompanionScrapping(CompanionScrappingAction companionScrappingAction)
	{
		GetComponent<CompanionEffects>().SavePreviousEffects();
		currentCorruption = maxCorruption;
		UpdateCorruption(CorruptionPurifyModifierEnum.NONE);
		companionSpriteControl.PlayReceiveFatalDamageInstantlyDefeatCompanionScrapping(companionScrappingAction);
		CompanionCompletelyCorruptedCallbacks();
	}

	protected override void UpdateCorruption(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (currentCorruption < 0f)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerAndSentinelsExceededPurify(-(int)currentCorruption);
		}
		base.UpdateCorruption(corruptionPurifyModifierEnum);
		companionCorruptionGauge.UpdateCorruptionGauge(currentCorruption);
	}

	protected override void CorruptedMoreThanPurified()
	{
		if (currentCorruption == maxCorruption)
		{
			CompanionCompletelyCorrupted();
		}
		else
		{
			spriteControl.OnReceiveCorruption();
		}
	}

	protected override void PurifiedMoreThanCorrupted()
	{
		spriteControl.OnReceivePurify();
	}

	protected void CompanionCompletelyCorrupted()
	{
		Debug.Log("**** CompanionCompletelyCorrupted: " + completelyCorrupted + " ****");
		if (completelyCorrupted)
		{
			spriteControl.OnReceiveCorruption();
			return;
		}
		GetComponent<CompanionEffects>().SavePreviousEffects();
		if (!(unitEffects as CompanionEffects).JustRecycled)
		{
			completelyCorrupted = true;
			spriteControl.OnReceiveFatalDamage();
			CompanionCompletelyCorruptedCallbacks();
		}
	}

	private void CompanionCompletelyCorruptedCallbacks()
	{
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.BrokenSentinelAmount++;
		ReferenceSingleton<AssetsReference>.Instance.IndigoRiteAction.IndigoRiteTriggerCheck();
		ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction?.Invoke();
	}

	public void DisableAliveCompanion(bool playerCompletelyCorrupted)
	{
		GetComponent<CompanionInitializer>().SentinelAutoRepairHUD.Initialize(playerCompletelyCorrupted);
		ToggleAliveAndFaintedCompanion(value: false);
	}

	public void ToggleAliveAndFaintedCompanion(bool value)
	{
		aliveCompanion.SetActive(value);
		faintedCompanion.SetActive(!value);
	}

	public void ToggleAliveCompanion(bool value)
	{
		aliveCompanion.SetActive(value);
	}

	public void InitializeAugmentedWelding()
	{
		currentAugmentedWeldingAmount = 0;
	}

	public void IncreaseMaxCorruption(int amount)
	{
		maxCorruption = originalMaxCorruption + amount;
		currentCorruption += amount - currentAugmentedWeldingAmount;
		currentAugmentedWeldingAmount = amount;
		companionCorruptionGauge.UpdateMaxCorruption(currentCorruption, (int)maxCorruption);
	}

	public void DecreaseMaxCorruption(int amount)
	{
		maxCorruption = originalMaxCorruption - amount;
		companionCorruptionGauge.UpdateMaxCorruption(currentCorruption, (int)maxCorruption);
	}

	public override bool IsDefeated()
	{
		return currentCorruption == maxCorruption;
	}
}
